import{_ as p,a0 as i,w as l,s as o,ao as s,I as a,x as e,a1 as u,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"如何在 Ubuntu 中加密硬盘 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中加密硬盘 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中加密硬盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中加密硬盘 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170113 How to Encrypt Your Hard Disk in Ubuntu","title":"如何在 Ubuntu 中加密硬盘","tag":"201702","desc":""},"relativePath":"201702/20170113 How to Encrypt Your Hard Disk in Ubuntu.md","filePath":"[post].md"}'),d={name:"201702/20170113 How to Encrypt Your Hard Disk in Ubuntu.md"};function m(b,t,f,k,h,y){const n=i("Link");return l(),o("div",null,[t[26]||(t[26]=s('<h1 id="如何在-ubuntu-中加密硬盘" tabindex="-1">如何在 Ubuntu 中加密硬盘 <a class="header-anchor" href="#如何在-ubuntu-中加密硬盘" aria-label="Permalink to “如何在 Ubuntu 中加密硬盘”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/hdd-encryption-ubuntu.jpg" alt="" title="How to Encrypt Your Hard Disk in Ubuntus"></p><p>隐私保护、安全和加密是不可分开的，用户可以通过加密来提高安全和保护操作系统的隐私信息。本文将会介绍在 Ubuntu Linux 中对硬盘全盘加密的优缺点。此外，我们也介绍如何在系统级别上进行加密设置，并对一些目录进行加密。加密是非常有用的，而且也没有你想象中那么复杂。综上所述，让我开始进行加密吧。</p><h3 id="加密的优缺点" tabindex="-1">加密的优缺点 <a class="header-anchor" href="#加密的优缺点" aria-label="Permalink to “加密的优缺点”">​</a></h3><p>尽管进行全盘加密听起来非常棒，但是否要这么做还是有些争议的。我们先来看看这个做法有哪些优缺点。</p><h4 id="加密的优点" tabindex="-1">加密的优点 <a class="header-anchor" href="#加密的优点" aria-label="Permalink to “加密的优点”">​</a></h4><ul><li>提高私密程度</li><li>只有拥有密钥的人才能访问操作系统及其中文件</li><li>确保政府或者黑客无法侦测你的系统和侵犯你的隐私</li></ul><h4 id="加密的缺点" tabindex="-1">加密的缺点 <a class="header-anchor" href="#加密的缺点" aria-label="Permalink to “加密的缺点”">​</a></h4><ul><li>在其他的 Linux 操作系统上访问和挂载文件系统将变得困难</li><li>无法从那些加密分区中恢复数据</li><li>如果用户丢失了加密密钥，那就彻底悲剧了</li></ul><h3 id="安装前的准备" tabindex="-1">安装前的准备 <a class="header-anchor" href="#安装前的准备" aria-label="Permalink to “安装前的准备”">​</a></h3>',10)),a("p",null,[t[2]||(t[2]=e("在 Ubuntu 中加密最好就是在安装进程开始之前在系统层面进行。在 Ubuntu 安装进程开始之后是无法加密的，所以先备份你的重要数据到 ",-1)),u(n,{href:"http://www.maketecheasier.com/tag/dropbox"},{default:r(()=>[...t[0]||(t[0]=[e("Dropbox",-1)])]),_:1}),t[3]||(t[3]=e("、 ",-1)),u(n,{href:"http://www.maketecheasier.com/tag/google-drive"},{default:r(()=>[...t[1]||(t[1]=[e("Google Drive",-1)])]),_:1}),t[4]||(t[4]=e(" （或者其它硬盘上），然后后准备重新安装 Ubuntu。",-1))]),t[27]||(t[27]=a("p",null,[a("img",{src:"https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-ubuntu-alternative-downloads.jpg",alt:"ubuntu 下载",title:"ubuntu-encrypt-ubuntu-alternative-downloads"})],-1)),a("p",null,[t[6]||(t[6]=e("从 ",-1)),u(n,{href:"https://www.ubuntu.com/download/alternative-downloads"},{default:r(()=>[...t[5]||(t[5]=[e("此处",-1)])]),_:1}),t[7]||(t[7]=e(" 开始下载最新版本的 Ubuntu，并制作好可启动的 U 盘 （需要至少 2 GB 可用空间）。",-1))]),a("p",null,[t[9]||(t[9]=e("制作启动 U 盘需要一个烧录程序，可以到 ",-1)),u(n,{href:"https://etcher.io/"},{default:r(()=>[...t[8]||(t[8]=[e("etcher.io",-1)])]),_:1}),t[10]||(t[10]=e(" 去下载。下载好之后解压 zip 文件，右击 (或者使用鼠标选定之后按下回车) 解压出来的文件以运行。",-1))]),t[28]||(t[28]=s('<p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-etcher.jpg" alt="烧录程序" title="ubuntu-encrypt-etcher"></p><p><strong>注意</strong>：烧录程序会询问是否创建图标，选择“yes”。</p><p>在烧录程序中点击“选择镜像（Select Image）”按钮，选择之前下载好的 Ubuntu ISO 镜像。然后插入你的 U 盘。烧录程序会自动检测并为你选择。最后，点击“开始烧录（ Flash）”按钮来开始创建进程。</p><p>完成之后，重启电脑至 BIOS，设置为 U 盘启动。</p><p><strong>注意</strong>：如果你的电脑不支持从 U 盘启动，下载 32 位的 Ubuntu，并使用你电脑中的烧录软件将其烧录到 DVD 中。</p><h3 id="对你的硬盘进行全盘加密" tabindex="-1">对你的硬盘进行全盘加密 <a class="header-anchor" href="#对你的硬盘进行全盘加密" aria-label="Permalink to “对你的硬盘进行全盘加密”">​</a></h3><p>加载好 Live Ubuntu 之后，安装进程就可以开始了。当 Ubuntu 安装进程开始之后，会出现下面这样一个界面。注意每个人安装进程都可能不同的，或许你会看到的不太一样。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-installation-type1.jpg" alt="" title="ubuntu-encrypt-installation-type"></p><p>选择“擦除磁盘并安装 Ubuntu （Erase disk and install Ubuntu）”,并选择“加密新装的 Ubuntu 以提高安全程度（Encrypt the new Ubuntu installation for Security）”来开始加密的安装进程。这样会自动选择 LVM。两个选框都必须选中。选好加密选项之后，点击“现在安装（Install Now）”。</p><p><strong>注意</strong>：如果是双系统启动的话，你需要安装到空余磁盘空间，而非擦除磁盘。选择好之后，像上边一样选择加密选项。</p><p>选择加密选项并开始安装之后，会出现一个加密配置页面。这个页面用户需要为安装进程设置自己的加密密钥。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-choose-security-key.jpg" alt="设置安全密码" title="ubuntu-encrypt-choose-security-key"></p><p>输入安全密钥。该安全密钥设置窗口会自动为你输入的密钥进行密码强度评级，使用这个功能时看着后边的显示，直到显示为“高强度密码（strong password）”为止。输入完成后，在下方在此输入来确认密码，最后用一张纸把密码写下下来妥善保管。</p><p>此外，选定“覆些磁盘空余空间（Overwrite empty disk space）”，当然这是一个可选步骤。一切准备就绪之后点击现在安装即可。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-timezone-select.jpg" alt="选择时区" title="ubuntu-encrypt-timezone-select"></p><p>在设置完加密密钥之后，就是传统的 Ubuntu 安装配置了。选择时区、创建用户以及对应的安全密码。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-home-folder-e1483900399596.jpg" alt="加密家目录" title="ubuntu-encrypt-home-folder"></p><p>与创建和加密 Ubuntu 磁盘对应，在创建用户的时记得候选择“登录系统需要密码（require my password to log in）”和“加密我的家目录（encrypt my home folder）”。这样可以为你的数据再增加一层保护。</p><p>等到用户名、加密设置以及其他所有事情都完成之后，Ubuntu 安装进程就可以开始了。随后，安装进程会告知你安装已完成，移除安装介质后重启即可享受 Ubuntu 之旅。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>进行磁盘加密之后，如果没有加密密钥则无法开启 Ubuntu。尽管无趣，但这种级别的加密使用最容易的，并且还充分利用了操作系统提供的特性。用户不需要过多的知识，或者使用其他第三方程序就可以很快完成加密要求。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/01/ubuntu-encrypt-decrypt-computer.jpg" alt="加密电脑" title="ubuntu-encrypt-decrypt-computer"></p><p>加密之后的 Ubuntu，使用起来和没有加密的并没有什么区别。不需要其他的步骤，也不需要学习什么复杂的解密方法。对于那些非常在意隐私但又不想太过麻烦的人来说，这个提高安全等级的方法是必须学会的（当然，这很容易不是吗）。</p><p>你是否会使用 Ubuntu 对硬盘进行加密呢？在下方评论告诉我们。</p><hr><p>译者简介：</p>',26)),a("p",null,[u(n,{href:"http://GHLandy.com"},{default:r(()=>[...t[11]||(t[11]=[e("GHLandy",-1)])]),_:1}),t[12]||(t[12]=e(" —— 欲得之，则为之奋斗 (If you want it, work for it.)。",-1))]),t[29]||(t[29]=a("hr",null,null,-1)),a("p",null,[t[14]||(t[14]=e("via: ",-1)),u(n,{href:"https://www.maketecheasier.com/encrypt-hard-disk-in-ubuntu/"},{default:r(()=>[...t[13]||(t[13]=[e("https://www.maketecheasier.com/encrypt-hard-disk-in-ubuntu/",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=e("作者：",-1)),u(n,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:r(()=>[...t[15]||(t[15]=[e("Derrik Diener",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),u(n,{href:"https://github.com/GHLandy"},{default:r(()=>[...t[16]||(t[16]=[e("GHLandy",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),u(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[23]||(t[23]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),u(n,{href:"https://linux.cn/"},{default:r(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const x=p(d,[["render",m]]);export{U as __pageData,x as default};
